package org.apache.commons.codec.net;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.util.*;
import java.util.BitSet;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringDecoder;
import org.apache.commons.codec.StringEncoder;
import org.apache.commons.codec.binary.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class QuotedPrintableCodec_encodeQuotedPrintable_TriageGen2Test {

    private static final BitSet PRINTABLE_CHARS = new BitSet();
    static {
        // Simulating a standard printable set for testing purposes
        for (int i = 32; i <= 126; i++) {
            PRINTABLE_CHARS.set(i);
        }
    }

    @Test
    public void testEncodeQuotedPrintable_NullBytes() {
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(PRINTABLE_CHARS, null);
        assertNull(result);
    }

    @Test
    public void testEncodeQuotedPrintable_NullPrintable() {
        // When printable is null, it should use PRINTABLE_CHARS internally
        byte[] input = "abc".getBytes();
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(null, input);
        assertArrayEquals("abc".getBytes(), result);
    }

    @Test
    public void testEncodeQuotedPrintable_AllPrintable() {
        byte[] input = "Hello World".getBytes();
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(PRINTABLE_CHARS, input);
        assertArrayEquals(input, result);
    }

    @Test
    public void testEncodeQuotedPrintable_NonPrintable() {
        // 0x00 is non-printable. In QuotedPrintable, it should be encoded as =00
        byte[] input = {0x00};
        byte[] expected = "=00".getBytes();
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(PRINTABLE_CHARS, input);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testEncodeQuotedPrintable_NegativeByte() {
        // Testing the logic: if (b < 0) { b = 256 + b; }
        // -1 as a byte is 0xFF (255)
        byte[] input = {(byte) -1};
        // 255 is non-printable, should be =FF
        byte[] expected = "=FF".getBytes();
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(PRINTABLE_CHARS, input);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testEncodeQuotedPrintable_MixedContent() {
        // Mix of printable and non-printable
        byte[] input = {'A', (byte) 0x01, 'B'};
        // 'A' is 65, 0x01 is non-printable (=01), 'B' is 66
        byte[] expected = {'A', '=', '0', '1', 'B'};
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(PRINTABLE_CHARS, input);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testEncodeQuotedPrintable_BoundaryValues() {
        // Test byte 127 (DEL) which is often non-printable
        BitSet customPrintable = new BitSet();
        customPrintable.set(65); // Only 'A' is printable

        byte[] input = {65, 127};
        // 65 -> 'A', 127 -> '=7F'
        byte[] expected = {'A', '=', '7', 'F'};
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(customPrintable, input);
        assertArrayEquals(expected, result);
    }
}
